#!/usr/bin/env node
/**
 * Single-sources the chat-proxy's server-held content from the client sources of truth:
 *
 *   src/personas.ts        -> supabase/functions/chat-proxy/personas.ts  (PERSONA_PROMPTS)
 *   src/data/catechism.ts  -> supabase/functions/chat-proxy/catechism.ts (verbatim data)
 *
 * The server copies used to be maintained by hand under a "keep in sync" comment, and they
 * drifted (the server's Ignatius still described a five-step examen after the app moved to
 * six). Never edit the generated files directly — edit the client source and re-run:
 *
 *   npm run sync:prompts     regenerate
 *   npm run check:prompts    fail if the generated files are stale (also covered by tests)
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const checkOnly = process.argv.includes('--check');

const EXPECTED_IDS = ['joseph', 'david', 'paul', 'augustine', 'ignatius', 'peter', 'moses', 'therese'];

function extractPersonaPrompts() {
  const src = readFileSync(join(root, 'src/personas.ts'), 'utf8');
  const prompts = {};
  const re = /systemPrompt:\s*`([\s\S]*?)`,/g;
  let match;
  while ((match = re.exec(src)) !== null) {
    const before = src.slice(0, match.index);
    const idMatches = [...before.matchAll(/\bid:\s*'([a-z-]+)'/g)];
    const id = idMatches[idMatches.length - 1][1];
    prompts[id] = match[1];
  }
  const ids = Object.keys(prompts);
  const missing = EXPECTED_IDS.filter((id) => !prompts[id]);
  if (missing.length || ids.length !== EXPECTED_IDS.length) {
    throw new Error(`Persona extraction failed. Found [${ids}], missing [${missing}]`);
  }
  return prompts;
}

function generatePersonasFile() {
  const prompts = extractPersonaPrompts();
  const entries = EXPECTED_IDS
    .map((id) => `  ${JSON.stringify(id)}: ${JSON.stringify(prompts[id])},`)
    .join('\n');
  return `// GENERATED by scripts/sync-server-prompts.mjs from src/personas.ts — do not edit by hand.
// Persona prompts held SERVER-SIDE on purpose (security): the client selects a persona by id,
// it never supplies prompt text, so the companion instructions and the safety framing around them
// cannot be replaced by a crafted request.
export const PERSONA_PROMPTS: Record<string, string> = {
${entries}
};

export function isPersonaId(value: unknown): value is string {
  return typeof value === "string" && Object.prototype.hasOwnProperty.call(PERSONA_PROMPTS, value);
}
`;
}

function generateCatechismFile() {
  const body = readFileSync(join(root, 'src/data/catechism.ts'), 'utf8');
  return `// GENERATED by scripts/sync-server-prompts.mjs from src/data/catechism.ts — do not edit by hand.\n${body}`;
}

const targets = [
  { path: 'supabase/functions/chat-proxy/personas.ts', generate: generatePersonasFile },
  { path: 'supabase/functions/chat-proxy/catechism.ts', generate: generateCatechismFile },
];

let drift = false;
for (const target of targets) {
  const generated = target.generate();
  const full = join(root, target.path);
  const current = readFileSync(full, 'utf8');
  if (current !== generated) {
    drift = true;
    if (checkOnly) {
      console.error(`DRIFT: ${target.path} is stale. Run: npm run sync:prompts`);
    } else {
      writeFileSync(full, generated);
      console.log(`synced ${target.path}`);
    }
  } else if (!checkOnly) {
    console.log(`already in sync: ${target.path}`);
  }
}
if (checkOnly && drift) process.exit(1);
if (checkOnly) console.log('server prompts in sync');
